package menus

import (
	"bytes"
	"encoding/hex"
	"encoding/json"
	"fmt"
	assetdata "gunship2000-assets/game/assets"
	"os"
	"path/filepath"
	"testing"
)

// The reference is generated by the separate Python source-record interpreter
// in evidence/stepE/assets. It reads original archive bytes, not Go metadata or
// composer output. This is a bounded static layer check, not a DOS frame claim.
func TestShipCompositionIndependentOriginalLayers(t *testing.T) {
	reference := os.Getenv("GS2000_TEST_SHIP_REFERENCE")
	prepared := os.Getenv("GS2000_TEST_PREFLIGHT")
	if reference == "" || prepared == "" {
		t.Skip("set GS2000_TEST_SHIP_REFERENCE and GS2000_TEST_PREFLIGHT")
	}
	raw, err := os.ReadFile(filepath.Join(reference, "cases.json"))
	if err != nil {
		t.Fatal(err)
	}
	var doc struct {
		Cases []struct {
			Label      string `json:"label"`
			Aircraft   int    `json:"aircraft"`
			Scene      int    `json:"scene"`
			RowHex     string `json:"row_hex"`
			Output     string `json:"output"`
			OutputHash string `json:"output_sha256"`
		} `json:"cases"`
	}
	if err := json.Unmarshal(raw, &doc); err != nil {
		t.Fatal(err)
	}
	if len(doc.Cases) != 3 {
		t.Fatalf("expected bounded three-case source reference, got %d", len(doc.Cases))
	}
	assets, err := assetdata.LoadMissionAssets(prepared)
	if err != nil {
		t.Fatal(err)
	}
	for _, c := range doc.Cases {
		t.Run(c.Label, func(t *testing.T) {
			rowRaw, err := hex.DecodeString(c.RowHex)
			if err != nil || len(rowRaw) != 36 {
				t.Fatal("reference requires complete36-byte row", err)
			}
			var row [36]byte
			copy(row[:], rowRaw)
			expected, err := os.ReadFile(filepath.Join(reference, c.Output))
			if err != nil || len(expected) != 64000 || assetdata.Hash(expected) != c.OutputHash {
				t.Fatal("independent reference integrity", err)
			}
			actual, err := preflightComposeShip(assets, c.Aircraft, c.Scene, row)
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(actual, expected) {
				different, first := 0, -1
				for i, v := range expected {
					if i >= len(actual) || actual[i] != v {
						different++
						if first < 0 {
							first = i
						}
					}
				}
				t.Fatalf("%d differences, first x%d/y%d", different, first%320, first/320)
			}
			t.Logf("64000 bytes match source-record layer reference, sha256 %s", assetdata.Hash(actual))
			if output := os.Getenv("GS2000_TEST_SHIP_OUTPUT"); output != "" {
				name := filepath.Join(output, c.Label+".png")
				if err := writeIndexedFrame(name, actual, assets.Palettes["FIELD.PAL"], prepared, map[string]any{"case": c.Label, "source_reference": reference, "scope": "independent static source-record layer comparison; no original-game frame capture", "aircraft": c.Aircraft, "scene": c.Scene}); err != nil {
					t.Fatal(fmt.Errorf("write diagnostic: %w", err))
				}
			}
		})
	}
}
